using System.ComponentModel.DataAnnotations;

namespace sv_e348ec978aff4ceeb6581d4d964a8f4c.Models;

public class RegistrationModel
{
    [Required(ErrorMessage = "Attendee name is required.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Range(0, 5, ErrorMessage = "Number of guests must be between 0 and 5.")]
    public int NumberOfGuests { get; set; }

    [Required(ErrorMessage = "Please select a preferred session.")]
    public string PreferredSession { get; set; } = string.Empty;

    public string? DietaryRequirements { get; set; }
}

namespace sv_e348ec978aff4ceeb6581d4d964a8f4c.Services;

public class RegistrationResult
{
    public bool Succeeded { get; init; }
    public Dictionary<string, string> FieldErrors { get; init; } = new();
}

public class RegistrationService
{
    /// <summary>
    /// Validates and processes a registration request.
    /// Returns field-specific errors if validation fails.
    /// </summary>
    public Task<RegistrationResult> ValidateAsync(string email)
    {
        var result = new RegistrationResult();

        // Simulate checking if the email is already registered
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            return Task.FromResult(new RegistrationResult
            {
                Succeeded = false,
                FieldErrors = new Dictionary<string, string>
                {
                    [nameof(Models.RegistrationModel.Email)] = "This email is already registered."
                }
            });
        }

        return Task.FromResult(new RegistrationResult { Succeeded = true });
    }
}

@page "/register"
@rendermode InteractiveServer
@using sv_e348ec978aff4ceeb6581d4d964a8f4c.Models
@using sv_e348ec978aff4ceeb6581d4d964a8f4c.Services
@inject RegistrationService RegistrationService

<PageTitle>Event Registration</PageTitle>

<h1>Event Registration</h1>

@if (registrationComplete)
{
    <div class="alert alert-success">
        <strong>Registration successful!</strong> You have been registered for the event.
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="register">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="name" class="form-label">Attendee Name</label>
            <InputText id="name" class="form-control" @bind-Value="model.Name" />
            <ValidationMessage For="() => model.Name" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
            @if (!string.IsNullOrEmpty(emailError))
            {
                <div class="validation-message">@emailError</div>
            }
        </div>

        <div class="mb-3">
            <label for="guests" class="form-label">Number of Guests</label>
            <InputNumber id="guests" class="form-control" @bind-Value="model.NumberOfGuests" />
            <ValidationMessage For="() => model.NumberOfGuests" />
        </div>

        <div class="mb-3">
            <label for="session" class="form-label">Preferred Session</label>
            <InputSelect id="session" class="form-control" @bind-Value="model.PreferredSession">
                <option value="">-- Select a session --</option>
                <option value="Morning">Morning</option>
                <option value="Afternoon">Afternoon</option>
                <option value="Evening">Evening</option>
            </InputSelect>
            <ValidationMessage For="() => model.PreferredSession" />
        </div>

        <div class="mb-3">
            <label for="dietary" class="form-label">Special Dietary Requirements</label>
            <InputTextArea id="dietary" class="form-control" @bind-Value="model.DietaryRequirements" />
        </div>

        <button type="submit" class="btn btn-primary" disabled="@isSubmitting">
            @(isSubmitting ? "Registering..." : "Register")
        </button>
    </EditForm>
}

@code {
    private RegistrationModel model = new();
    private string? emailError;
    private bool isSubmitting;
    private bool registrationComplete;

    private async Task HandleSubmit()
    {
        emailError = null;
        isSubmitting = true;

        try
        {
            var result = await RegistrationService.ValidateAsync(model.Email);

            if (!result.Succeeded)
            {
                if (result.FieldErrors.TryGetValue(nameof(model.Email), out var error))
                {
                    emailError = error;
                }
                return;
            }

            registrationComplete = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

